<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$q=trim((string)($_GET['q']??''));$cat=(int)($_GET['categorie']??0);$compagnie=(int)($_GET['compagnie']??0);$page=max(1,(int)($_GET['page']??1));$per=20;$w=[];$p=[];if($q!==''){$w[]='(p.code_produit LIKE :q OR p.nom LIKE :q)';$p['q']='%'.$q.'%';}if($cat){$w[]='p.categorie_id=:cat';$p['cat']=$cat;}if($compagnie){$w[]='p.compagnie_id=:cie';$p['cie']=$compagnie;}$where=$w?' WHERE '.implode(' AND ',$w):'';$s=$db->prepare('SELECT COUNT(*) FROM produits_assurance p'.$where);$s->execute($p);$total=(int)$s->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$s=$db->prepare("SELECT p.*,c.raison_sociale,cr.libelle categorie,(SELECT COUNT(*) FROM produits_garanties pg WHERE pg.produit_id=p.id) nb_garanties FROM produits_assurance p JOIN compagnies c ON c.id=p.compagnie_id JOIN categories_risque cr ON cr.id=p.categorie_id $where ORDER BY p.nom LIMIT :lim OFFSET :off");foreach($p as $k=>$v)$s->bindValue(':'.$k,$v);$s->bindValue(':lim',$per,PDO::PARAM_INT);$s->bindValue(':off',($page-1)*$per,PDO::PARAM_INT);$s->execute();$rows=$s->fetchAll();$categories=$db->query('SELECT id,libelle FROM categories_risque ORDER BY libelle')->fetchAll();$compagnies=$db->query("SELECT id,raison_sociale FROM compagnies ORDER BY raison_sociale")->fetchAll();$title='Produits';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Produits d’assurance</h1><p class="text-secondary"><?= $total ?> produit(s)</p></div><a class="btn btn-primary" href="form.php">+ Nouveau produit</a></div><form class="filter-bar filter-four" method="get"><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Code ou produit"><select class="form-select" name="compagnie"><option value="0">Toutes les compagnies</option><?php foreach($compagnies as $c): ?><option value="<?= $c['id'] ?>" <?= $compagnie==(int)$c['id']?'selected':'' ?>><?= e($c['raison_sociale']) ?></option><?php endforeach ?></select><select class="form-select" name="categorie"><option value="0">Tous les risques</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $cat==(int)$c['id']?'selected':'' ?>><?= e($c['libelle']) ?></option><?php endforeach ?></select><button class="btn btn-dark">Filtrer</button></form><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Produit</th><th>Compagnie</th><th>Risque</th><th>Prime de base</th><th>Garanties</th><th>Statut</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['nom']) ?></strong><div class="small text-secondary"><?= e($r['code_produit']) ?></div></td><td><?= e($r['raison_sociale']) ?></td><td><span class="badge rounded-pill text-bg-info"><?= e($r['categorie']) ?></span></td><td><?= number_format((float)$r['prime_base'],0,',',' ') ?> FCFA</td><td><?= (int)$r['nb_garanties'] ?></td><td><?= e($r['statut']) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="form.php?id=<?= (int)$r['id'] ?>">Modifier</a> <form class="d-inline" method="post" action="delete.php" data-confirm="Supprimer ce produit ?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Supprimer</button></form></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty-state">Aucun produit trouvé.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
